"""Create a portable, self-contained engineering handover (no external assets needed)."""
from pathlib import Path
import base64
import html
import io
import json
import re
from markdown_it import MarkdownIt
from PIL import Image

ROOT = Path(__file__).resolve().parents[1]
SECTIONS = [
    ('upgrade','01','Ground-level upgrade','docs/v2/AUDIT_REPORT.md'),
    ('review','02','Read-only upstream audit','docs/UPSTREAM_AUDIT.md'),
    ('architecture','03','System architecture','docs/ARCHITECTURE.md'),
    ('models','04','Transparent model cards','docs/v2/MODEL_CARDS.md'),
    ('science','05','Existing scientific methods','docs/SCIENTIFIC_METHODS.md'),
    ('providers','06','APIs and accounts','docs/API_GUIDE.md'),
    ('local','07','Run locally','docs/LOCAL_RUN.md'),
    ('publish','08','Publish source to GitHub','docs/GITHUB_PUBLISH.md'),
    ('security','09','Security and deployment','docs/SECURITY.md'),
    ('verification','10','Verification evidence','docs/VALIDATION.md'),
    ('licenses','11','Attribution and licenses','THIRD_PARTY_NOTICES.md'),
]

def image_uri(name, width=1440):
    image = Image.open(ROOT / 'docs/previews' / name).convert('RGB')
    image.thumbnail((width, 1200))
    buffer = io.BytesIO()
    image.save(buffer, format='JPEG', quality=84, optimize=True)
    return 'data:image/jpeg;base64,' + base64.b64encode(buffer.getvalue()).decode()

def main():
    md = MarkdownIt('commonmark', {'html': False}).enable('table')
    sections = []
    for key, number, title, file in SECTIONS:
        body = md.render((ROOT / file).read_text())
        body = re.sub(r'<(/?)h([1-5])>', lambda m: f'<{m[1]}h{int(m[2])+1}>', body)
        body = body.replace('<table>', '<div class="table-scroll"><table>').replace('</table>', '</table></div>')
        body = re.sub(r'<a href="(https?://[^"]+)"', r'<a target="_blank" rel="noopener noreferrer" href="\1"', body)
        sections.append(f'<section class="doc" id="{key}"><div class="chapter">CHAPTER {number} / {title.upper()}</div>{body}</section>')
    menu = ''.join(f'<a href="#{key}"><span>{number}</span>{title}</a>' for key, number, title, _ in SECTIONS)
    shot = image_uri('../v2/screenshots/chromium-overview-1440x960.png')
    soil = image_uri('../v2/screenshots/chromium-signals-1440x960.png', 1100)
    scenario = image_uri('../v2/screenshots/comparison-desktop.png', 1100)
    diagram = (ROOT / 'docs/v2/architecture.svg').read_text()
    verification = json.loads((ROOT / 'docs/v2/browser-verification-v2.json').read_text())
    stamp = html.escape(verification['finished'])
    content = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>ATLAS 2.0 · Engineering handover</title><style>
:root{{--ink:#173037;--muted:#627778;--mint:#97e4c9;--green:#246c59;--paper:#f4f6f3;--line:#d6dfd8}}
*{{box-sizing:border-box}}html{{scroll-behavior:smooth;scroll-padding-top:30px}}body{{margin:0;background:var(--paper);color:var(--ink);font:15px/1.7 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}}a{{color:var(--green);text-underline-offset:3px}}aside{{width:242px;background:#0c1920;color:#d1e6df;position:fixed;inset:0 auto 0 0;padding:34px 24px;overflow:auto;z-index:2}}.brand{{font-size:24px;letter-spacing:5px;font-weight:700;color:#f0faf6}}.brand b{{color:var(--mint);font-size:33px;letter-spacing:0}}.strap{{font-size:9px;letter-spacing:2.7px;color:#8caaa7;margin-top:6px}}.nav-caption{{color:#7d9b96;font-size:10px;letter-spacing:1.8px;margin:48px 0 16px}}aside a{{display:block;color:#c2d6d2;text-decoration:none;font-size:12px;padding:11px 0;border-bottom:1px solid #26383d}}aside a:hover{{color:var(--mint)}}aside a span{{display:inline-block;font:10px ui-monospace,monospace;width:27px;color:#6e9990}}.side-note{{margin-top:35px;font-size:11px;color:#8ea9a3;line-height:1.8}}main{{margin-left:242px;max-width:1460px}}.hero{{background:#0c1920;color:#e2eee9;padding:66px 7% 0;position:relative}}.eyebrow,.chapter{{font:10px ui-monospace,monospace;letter-spacing:2px;color:var(--green);font-weight:600}}.hero .eyebrow{{color:var(--mint)}}.hero h1{{font-size:clamp(34px,4.8vw,67px);line-height:1.09;font-weight:500;letter-spacing:-2.4px;margin:27px 0 23px;max-width:950px}}.hero h1 em{{color:var(--mint);font-family:Georgia,serif;font-weight:400}}.lede{{max-width:780px;color:#a8c1bd;font-size:16px;line-height:1.8}}.pill-row{{display:flex;gap:8px;flex-wrap:wrap;margin:28px 0 36px}}.pill{{border:1px solid #39534e;border-radius:4px;color:#c1d8cf;font-size:10px;padding:6px 10px;letter-spacing:.6px}}.hero img{{display:block;width:100%;border-radius:9px 9px 0 0;border:1px solid #39504f;border-bottom:0}}.hero-caption{{margin:0;padding:10px 7%;font-size:10px;background:#13252c;color:#b4c7bf}}.opening{{padding:35px 7% 0}}.metrics{{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:34px}}.metric{{border-bottom:2px solid #abcaba;padding:20px 0}}.metric strong{{font-size:32px;font-weight:500;display:block;letter-spacing:-1px}}.metric span{{font-size:11px;color:var(--muted)}}.intro-grid{{display:grid;grid-template-columns:1.15fr 1fr;gap:38px;margin:36px 0}}.intro-grid h2{{font:32px/1.2 Georgia,serif;letter-spacing:-.5px}}.intro-grid p{{font-size:14px}}.callout{{background:#e4eee7;border:1px solid #c6d9cb;border-left:4px solid #559b7c;padding:20px 24px;font-size:13px;margin:28px 0}}.callout strong{{display:block;margin-bottom:5px}}.diagram svg{{width:100%;height:auto;display:block;border-radius:10px}}.proofs{{display:grid;grid-template-columns:1fr 1fr;gap:15px;margin:25px 0}}figure{{margin:0}}figure img{{width:100%;display:block;border-radius:6px}}figcaption{{font-size:10px;color:#5b726b;padding-top:8px}}.doc{{padding:55px 7%;border-top:1px solid var(--line);scroll-margin-top:0}}.doc h2{{font:38px/1.17 Georgia,serif;letter-spacing:-.7px;margin:15px 0 28px}}.doc h3{{font-size:23px;line-height:1.35;letter-spacing:-.4px;margin:38px 0 16px}}.doc h4{{font-size:17px;line-height:1.4;margin-top:27px}}.doc h5{{font-size:15px}}.doc p,.doc li{{font-size:14px}}.doc p{{margin:15px 0}}.doc ul,.doc ol{{padding-left:24px}}.doc li{{margin-bottom:7px}}.table-scroll{{overflow-x:auto;margin:25px 0}}table{{border-collapse:collapse;width:100%;font-size:12px}}th{{text-align:left;background:#183a39;color:#e7f5ed;font-weight:500}}td,th{{padding:12px 13px;vertical-align:top;border-bottom:1px solid #cfdcd2;overflow-wrap:anywhere}}tr:nth-child(even) td{{background:#edf2ec}}td{{min-width:100px}}code{{font:12px/1.7 ui-monospace,SFMono-Regular,Consolas,monospace;background:#e4ebe3;color:#265e49;border-radius:3px;padding:2px 4px;overflow-wrap:anywhere}}pre{{background:#11272b;color:#d8ede5;padding:22px;border-radius:7px;overflow:auto;font:12px/1.7 ui-monospace,monospace;tab-size:2}}pre code{{padding:0;background:none;color:inherit;white-space:pre-wrap;overflow-wrap:anywhere}}blockquote{{border-left:3px solid #6faa8a;padding:4px 22px;color:#526f61;margin-left:0}}.end{{padding:32px 7% 60px;background:#0c1920;color:#91aaa2;font-size:12px}}.end strong{{color:#c4e6d5;display:block;font:20px Georgia,serif;margin-bottom:8px}}
@media(max-width:960px){{aside{{position:relative;width:auto;padding:22px 7%}}aside nav{{display:flex;flex-wrap:wrap;gap:0 18px}}aside nav a{{border:0;padding:6px 0}}.nav-caption,.side-note{{display:none}}main{{margin-left:0}}.hero{{padding-top:43px}}.metrics{{grid-template-columns:repeat(2,1fr)}}.intro-grid{{grid-template-columns:1fr;gap:0}}}}
@media(max-width:560px){{.proofs{{grid-template-columns:1fr}}.hero h1{{font-size:39px;letter-spacing:-1.4px}}.doc h2{{font-size:30px}}.doc{{padding:38px 6%}}.metric strong{{font-size:28px}}}}
@media(prefers-reduced-motion:reduce){{html{{scroll-behavior:auto}}}}
@media print{{@page{{size:A4;margin:16mm 14mm}}aside{{display:none}}main{{margin:0;max-width:none}}body{{font-size:10pt;background:white}}.hero{{padding:24px 25px 0}}.hero h1{{font-size:39px}}.lede{{font-size:11pt}}.opening,.doc{{padding:24px 0}}.doc{{break-before:page}}.doc h2{{font-size:27pt}}.doc h3{{font-size:16pt;break-after:avoid}}.doc h4{{break-after:avoid}}.doc p,.doc li{{font-size:9.5pt}}.chapter{{font-size:8pt}}td,th{{font-size:8pt;padding:8px;min-width:0}}tr,figure,.callout,.metrics,.diagram{{break-inside:avoid}}thead{{display:table-header-group}}.table-scroll{{overflow:visible}}pre{{white-space:pre-wrap;break-inside:auto}}a{{color:#246c59}}.hero-caption{{font-size:7.5pt}}.intro-grid{{gap:22px}}.end{{padding:24px}}}}
</style></head><body><aside><div class="brand"><b>Λ</b> ATLAS</div><div class="strap">EARTH INTELLIGENCE</div><div class="nav-caption">ENGINEERING HANDOVER</div><nav><a href="#overview"><span>00</span>Project overview</a>{menu}</nav><div class="side-note">v2.0.0 · 10 October 2026<br>Source-complete research application.<br><br>This is an offline guide. The live app is a separate Arena preview. Screenshots are recorded evidence, not streaming data.</div></aside><main>
<header class="hero" id="overview"><div class="eyebrow">TERRAWATCH × OSIRIS / A WORKING, ORIGINAL INTEGRATION</div><h1>Earth intelligence,<br><em>without false certainty.</em></h1><p class="lede">A live geospatial workspace built around public-source evidence, transparent environmental methods and explicit uncertainty. Read-only upstream review. Original implementation. Reproducible handover.</p><div class="pill-row"><span class="pill">COMPLETE SOURCE + BUILT FRONTEND</span><span class="pill">REAL API DATA</span><span class="pill">BOUNDED, TESTED EXECUTION</span></div><img src="{shot}" alt="Actual ATLAS desktop browser screenshot"></header><p class="hero-caption">Recorded browser verification: {stamp} · Provider counts and environmental values change over time.</p>
<div class="opening"><div class="metrics"><div class="metric"><strong>552</strong><span>upstream text files triaged read-only</span></div><div class="metric"><strong>23</strong><span>implemented provider adapters</span></div><div class="metric"><strong>303</strong><span>passing offline tests · 225 backend + 78 client</span></div><div class="metric"><strong>36</strong><span>browser flows · plus 72 viewport samples</span></div><div class="intro-grid"><div><div class="eyebrow">THE DELIVERABLE</div><h2>Not just a blueprint.<br>A working project.</h2><p>Dono repositories ko clone kiye bina source-level review kiya gaya. Environmental analysis aur multi-source map ko ek working application mein combine kiya hai—backend, frontend, real adapters, reports, exports aur tests ke saath.</p><p><strong>Live demo:</strong> open the <strong>ATLAS 2 · Earth Intelligence</strong> preview in this conversation. It is temporary workspace hosting; your permanent server choice remains open.</p></div><div><div class="eyebrow">YOUR HANDOVER PACKAGE</div><p><strong>ATLAS-2.0-project.zip</strong> contains the complete original source, compiled frontend, lock files, tests, Docker/Compose and CI definitions, documentation and verification artifacts.</p><p>Extract it, follow <code>README.md</code>, and run <code>./scripts/setup.sh</code> followed by <code>./scripts/run.sh</code>. Python 3.13 + Node 24 are the recommended build environment. A prebuilt-frontend path does not need Node merely to run.</p><p>This guide is self-contained. Images, diagrams and styles are embedded; no external scripts, fonts or network assets are needed to read it.</p></div></div><div class="callout"><strong>Where the evidence stops</strong>GDELT was unavailable in live checks. The optional NASA FIRMS Area adapter needs a real free MAP_KEY. Cold SoilGrids requests can be partial or unavailable. Native Windows/macOS and physical devices were not executed here. GitHub push is blocked without an authenticated destination; the local publishing helper is supplied. Free hosted Open-Meteo use is non-commercial. Docker execution, production load/soak testing, security certification and empirical hazard calibration are not claimed.</div><div class="diagram">{diagram}</div><div class="proofs"><figure><img src="{soil}" alt="Actual Signal Lab screenshot with complete-window metrics"><figcaption>Signal Lab: explicit equations, complete-window coverage and real modeled inputs—not observations.</figcaption></figure><figure><img src="{scenario}" alt="Actual common-clock location-comparison screenshot"><figcaption>Shared-clock point comparison: like-for-like methods, not an invented city-safety ranking.</figcaption></figure></div></div>
{''.join(sections)}<footer class="end"><strong>Built on evidence. Every signal has a source.</strong>Original ATLAS integration · MIT for original code; separate third-party/data licenses apply. Do not interpret a missing report as an all-clear. This handover is not an emergency-service, scientific or security certification.</footer></main></body></html>'''
    (ROOT.parent / 'ATLAS-2.0-handover.html').write_text(content)
    (ROOT / 'docs/HANDOVER.html').write_text(content)
    print('Portable handover generated:', len(content.encode()), 'bytes')

if __name__ == '__main__':
    main()
